import { Box, Inline, Button } from '@stripe/ui-extension-sdk/ui';
import { JvSectionHeader, JvEmptyState } from '../components/brand';

interface Conversation {
  id: string;
  title: string;
  updatedAt: string;
}

interface ConversationListProps {
  conversations: Conversation[];
  activeConversationId: string | null;
  onSelectConversation: (id: string) => void;
  onClose: () => void;
}

const ConversationList = ({
  conversations,
  activeConversationId,
  onSelectConversation,
  onClose,
}: ConversationListProps) => {
  if (conversations.length === 0) {
    return (
      <JvEmptyState
        title="No conversations yet"
        description="Start by asking a question below."
      />
    );
  }

  return (
    <Box css={{ stack: 'y', gap: 'xsmall', padding: 'small' }}>
      <JvSectionHeader
        title="Conversations"
        action={
          <Button type="secondary" size="small" onPress={onClose}>
            Close
          </Button>
        }
      />
      {conversations.map((conv) => (
        <Box
          key={conv.id}
          css={{
            padding: 'small',
            backgroundColor: conv.id === activeConversationId ? 'container' : undefined,
            stack: 'y',
            gap: 'xsmall',
          }}
        >
          <Button
            type="secondary"
            size="small"
            onPress={() => onSelectConversation(conv.id)}
          >
            <Box css={{ stack: 'y', gap: 'xsmall', width: 'fill' }}>
              <Inline css={{ fontWeight: conv.id === activeConversationId ? 'semibold' : 'regular' }}>
                {conv.title || 'Untitled conversation'}
              </Inline>
              <Inline css={{ font: 'caption', color: 'secondary' }}>
                {new Date(conv.updatedAt).toLocaleDateString()}
              </Inline>
            </Box>
          </Button>
        </Box>
      ))}
    </Box>
  );
};

export default ConversationList;
