import { Box, Inline } from '@stripe/ui-extension-sdk/ui';
import { JvFreshnessIndicator } from '../components/brand';

interface MessageBubbleProps {
  role: 'user' | 'assistant';
  content: string;
  freshness?: { type: 'cached' | 'live'; syncedAt?: string };
}

const MessageBubble = ({ role, content, freshness }: MessageBubbleProps) => {
  const isUser = role === 'user';

  return (
    <Box
      css={{
        padding: 'medium',
        backgroundColor: isUser ? 'container' : undefined,
        stack: 'y',
        gap: 'small',
      }}
    >
      <Inline css={{ fontWeight: 'semibold', color: 'secondary' }}>
        {isUser ? 'You' : 'Javelin'}
      </Inline>
      <Inline>{content}</Inline>
      {freshness && !isUser && (
        <Box css={{ marginTop: 'xsmall' }}>
          <JvFreshnessIndicator type={freshness.type} syncedAt={freshness.syncedAt} />
        </Box>
      )}
    </Box>
  );
};

export default MessageBubble;
